   "desc": "Binavkirinên dûzimanî di du formayan de ne: du rêz di yek nîşanê de, an du nîşan li ser heman demê. Aliyên erênî, neyînî, û meriv çawa di navbera wan de diguhere. – AI-SRTSub",
   "h1": "Du Rêyên Çêkirina Binavkirinên Dûzimanî",
